import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './Components/Navbar/Navbar'; // Your left sidebar component
import TopNavbar from './Components/Navbar/TopNavbar'; // The top search/sub-nav component
import Footer from './Components/Footer/Footer';
import Home from './Pages/Home';
import LoginSignup from './Pages/LoginSignup';
import Products from './Pages/Products';
import About from './Pages/About';
import Contact from './Pages/Contact';
import Cart from './Pages/Cart';
import Orders from './Pages/Orders';

function StoreLayout() {
  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', boxSizing: 'border-box', background: '#eaeded', overflowX: 'hidden' }}>

      {/* 1. Left Sidebar Navigation */}
      <div style={{ width: '250px', minWidth: '250px', height: '100vh', position: 'sticky', top: '0' }}>
        <Navbar />
      </div>

      {/* 2. Right Side Content Area */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: '100vh', overflowX: 'hidden' }}>

        {/* Top Search Bar & Sub-Nav Strip */}
        <TopNavbar />

        {/* Main Route Pages */}
        <main style={{ flex: 1, width: '100%', boxSizing: 'border-box' }}>
          <Routes>
            <Route path='/' element={<Home />} />
            <Route path='/products' element={<Products />} />
            <Route path='/about' element={<About />} />
            <Route path='/contact' element={<Contact />} />
            <Route path='/login' element={<LoginSignup />} />
            <Route path='/cart' element={<Cart />} />
            <Route path='/orders' element={<Orders />} />
          </Routes>
        </main>

        <Footer />
      </div>
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/*" element={<StoreLayout />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
